action_details.action_postfix:
// Physical nexus established - filing required
true result.mt_has_nexus xdef
"Montana filing required: Physical presence (office, employees, or property in state)" job.audit_trail swap addto

// Economic nexus established per Wayfair - filing required
true result.mt_has_nexus xdef
"Montana filing required: Economic nexus (exceeds $100,000 gross receipts or 200 transactions)" job.audit_trail swap addto

// Calculate Montana state additions
0.0 /mt_additions xdef

// Common Montana additions:
// - Federal bond interest
// - State tax refunds received
// - IRC 199A deduction (MT may not fully conform)
// - Expenses related to exempt income

result.mt_us_interest_income 0.0 ne
{
  mt_additions result.mt_us_interest_income add /mt_additions xdef
} if

mt_additions result.mt_state_additions xdef

// Calculate Montana state subtractions
0.0 /mt_subtractions xdef

// Common Montana subtractions:
// - Montana municipal bond interest
// - State income taxes paid
// - Montana NOL deduction

result.mt_municipal_interest 0.0 ne
{
  mt_subtractions result.mt_municipal_interest add /mt_subtractions xdef
} if

mt_subtractions result.mt_state_subtractions xdef

"Montana additions: $" result.mt_state_additions cvs strconcat ", subtractions: $" strconcat result.mt_state_subtractions cvs strconcat job.audit_trail swap addto

// Calculate Montana taxable income // Federal taxable income apportioned to MT + additions - subtractions result.mt_apportioned_income result.mt_state_additions add result.mt_state_subtractions sub 0.0 max result.mt_taxable_income xdef
// Calculate Montana tax using standard flat rate: 6.75% result.mt_taxable_income result.mt_corp_tax_rate mul /mt_tax_before_credits xdef
// Subtract Montana state credits (jobs creation, research, energy production, infrastructure, etc.) mt_tax_before_credits result.mt_state_credits sub 0.0 max result.mt_tax_liability xdef
// Calculate refund or amount owed result.mt_estimated_payments result.mt_tax_liability sub result.mt_refund_or_owed xdef
"Montana taxable income: $" result.mt_taxable_income cvs strconcat job.audit_trail swap addto "Montana tax liability (6.75% standard rate): $" result.mt_tax_liability cvs strconcat job.audit_trail swap addto

// Calculate Montana taxable income // Federal taxable income apportioned to MT + additions - subtractions result.mt_apportioned_income result.mt_state_additions add result.mt_state_subtractions sub 0.0 max result.mt_taxable_income xdef
// Calculate Montana tax using water's edge rate: 7.0% result.mt_taxable_income result.mt_corp_tax_rate_waters_edge mul /mt_tax_before_credits xdef
// Subtract Montana state credits mt_tax_before_credits result.mt_state_credits sub 0.0 max result.mt_tax_liability xdef
// Calculate refund or amount owed result.mt_estimated_payments result.mt_tax_liability sub result.mt_refund_or_owed xdef
"Montana taxable income: $" result.mt_taxable_income cvs strconcat job.audit_trail swap addto "Montana tax liability (7.0% water's edge rate): $" result.mt_tax_liability cvs strconcat job.audit_trail swap addto
